import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem118 preserva campos operacionais',()=>{for(const [id,titulo,expected,link] of [["nzEaLDNocvF6GDH6InIH","Colchonete Camping Camuflado Colchao dobravel Saco De Dormir Hezzo Hometech Pesca Acampamento Retiro Trilha C/ Saco De Transporte Mochila","Colchonete de camping camuflado — 190 × 60 cm anunciados","https://www.mercadolivre.com.br/p/MLB68897341?wid=MLB4655530173"],["o6oq1IPOS41xUDtF3TG7","Varal Aço Inox Suspenso Roupa Íntima 40 Prendedor Calcinha","Varal suspenso com 40 prendedores — aço inox anunciado","https://www.mercadolivre.com.br/up/MLBU3503517945?pdp_filters=item_id%3AMLB5832558364"],["O8vB8vB9Kw6NpVqHMt8A","Smartphone Motorola Moto G17 4g - 128gb 12gb (4gb Ram + 8gb Ram Boost), Camera 50mp Sony Lytia 600, Tela Fhd+ 60hz, Bateria 5200 Mah - Rosa","Motorola Moto G17 4G — 128 GB e 4 GB de RAM física","https://www.mercadolivre.com.br/p/MLB65041643?wid=MLB6420227790"]]){const p={id,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
